// The change notes of one release as the update window shows them, in the
// order of the release body. Text only: the window renders it with text
// bindings, never as HTML.
export type ChangeBlock =
  | { kind: 'label', text: string }
  | { kind: 'list', items: string[] }
  | { kind: 'paragraph', text: string }

// `formatReleaseBody` (scripts/release-notes.js) writes the notes under this
// heading, after the template, and ends them with a "generated by" line.
const CHANGES_HEADING = /^##[^\S\n]+Changes[^\S\n]*$/
const GENERATED_BY = /^Release notes generated by\b/
// An h1 or h2 that someone adds after the notes starts a new section.
const SECTION_HEADING = /^#{1,2}[^\S\n]/
// The notes group bullets under "**NEW**"-style lines; a hand-written
// "### Fixes" heading works the same.
const LABEL = /^(?:\*\*([^*]+)\*\*|#{3,6}[^\S\n]+(.+?)(?:[^\S\n]+#+)?)$/
const BULLET = /^[-*+][^\S\n]+(.+)$/
// A "---" or "***" line between parts of the notes.
const THEMATIC_BREAK = /^([-*_])(?:[^\S\n]*\1){2,}$/
// HTML tags and comments. GitHub's web editor adds screenshots as `<img>`
// lines (as in the v0.15.x releases), which a text view would show as raw
// markup, so they are taken out.
const HTML_TAG = /<!--[\s\S]*?-->|<\/?[A-Za-z][^<>]*>/g
// A Markdown image on a line of its own; like `<img>`, text cannot show it.
const IMAGE_LINE = /^!\[[^\]]*\]\([^)]*\)$/

// Returns the change notes of a release body: the part from "## Changes" up to
// the "Release notes generated by" line (or the next h1/h2, or the end). Label
// lines become labels, bullets become lists, and other lines become
// paragraphs. A body without "## Changes" (the model replied NONE, or someone
// wrote the release by hand) gives no blocks.
export function releaseChanges(body: string | null | undefined): ChangeBlock[] {
  if (!body) return []
  // Bodies edited on github.com have CRLF line ends.
  const lines = body.split(/\r?\n/).map((line) => line.trim())
  const start = lines.findIndex((line) => CHANGES_HEADING.test(line))
  if (start === -1) return []

  const blocks: ChangeBlock[] = []
  // Whether the previous line added to the last block, so that this line,
  // when it is plain text, continues it (Markdown's lazy continuation).
  let continuing = false
  for (const rawLine of lines.slice(start + 1)) {
    if (GENERATED_BY.test(rawLine) || SECTION_HEADING.test(rawLine)) break
    const line = IMAGE_LINE.test(rawLine) || THEMATIC_BREAK.test(rawLine)
      ? ''
      : rawLine.replace(HTML_TAG, '').trim()
    if (!line) {
      continuing = false
      continue
    }

    const last = blocks.at(-1)
    const label = LABEL.exec(line)
    const bullet = BULLET.exec(line)
    if (label) {
      blocks.push({ kind: 'label', text: (label[1] ?? label[2]).trim() })
      continuing = false
    } else if (bullet) {
      // A blank line between bullets (a loose list) keeps one list.
      if (last?.kind === 'list') {
        last.items.push(bullet[1])
      } else {
        blocks.push({ kind: 'list', items: [bullet[1]] })
      }
      continuing = true
    } else {
      if (continuing && last?.kind === 'list') {
        last.items[last.items.length - 1] += ` ${line}`
      } else if (continuing && last?.kind === 'paragraph') {
        last.text += ` ${line}`
      } else {
        blocks.push({ kind: 'paragraph', text: line })
      }
      continuing = true
    }
  }
  return blocks
}
